#include <algorithm>
#include <iostream>
#include <map>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    std::map<int, int> delta;
    for (int i = 0; i < n; ++i) {
        int s, e;
        std::cin >> s >> e;
        delta[s] += 1;
        delta[e] -= 1;              // half-open: the interval ends where it ends
    }

    int active = 0, peak = 0;
    for (auto [coord, change] : delta) {
        (void)coord;
        active += change;
        peak = std::max(peak, active);
    }
    std::cout << peak << '\n';
}
